import { createContext, useContext, useEffect, useState } from 'react'
import { NavLink, Route, Routes, useLocation, useParams } from 'react-router-dom'
import { warehouseService } from './application/useWarehouse'

const WarehouseContext = createContext(null)
const emptyData = { kpis: [], orders: [], stock: [], suppliers: [], invoices: [], procedures: [], events: [], alerts: [], alertRules: [], receipts: [] }
const useWarehouseData = () => useContext(WarehouseContext)

const nav = [
  { to: '/', label: 'Resumen', icon: 'bi-grid-1x2-fill', end: true },
  { to: '/pedidos', label: 'Pedidos y compras', icon: 'bi-cart3', count: '24' },
  { to: '/stock', label: 'Stock', icon: 'bi-box-seam' },
  { to: '/recepcion', label: 'Recepción y almacén', icon: 'bi-arrow-down-square' },
  { to: '/proveedores', label: 'Proveedores', icon: 'bi-building' },
  { to: '/documentos', label: 'Documentos y facturas', icon: 'bi-file-earmark-text', count: '3' },
  { to: '/eventos', label: 'Eventos y alertas', icon: 'bi-activity', count: '7' },
]

function App() {
  const [copilot, setCopilot] = useState(false)
  const [data, setData] = useState(emptyData)
  const loadData = () => warehouseService.loadAll().then(setData).catch(error => console.error('No se pudo cargar la API', error))
  const [newOrderOpen, setNewOrderOpen] = useState(false)
  const [importOpen, setImportOpen] = useState(false)
  const [invoiceOpen, setInvoiceOpen] = useState(false)
  const [procedureOpen, setProcedureOpen] = useState(false)
  useEffect(() => { loadData() }, [])
  return <WarehouseContext.Provider value={{ ...data, refresh: loadData }}><div className="app-shell">
    <main className="main-area">
      <Header onCopilot={() => setCopilot(true)} />
      <div className="page-content container"><Routes>
        <Route path="/" element={<Dashboard onNewOrder={() => setNewOrderOpen(true)} />} />
        <Route path="/pedidos" element={<Orders onNewOrder={() => setNewOrderOpen(true)} onImport={() => setImportOpen(true)} />} />
        <Route path="/pedidos/:id" element={<OrderDetail />} />
        <Route path="/stock" element={<Stock />} />
        <Route path="/recepcion" element={<ReceivingFromApi />} />
        <Route path="/proveedores" element={<Suppliers />} />
        <Route path="/documentos" element={<Documents onUploadInvoice={() => setInvoiceOpen(true)} onUploadProcedure={() => setProcedureOpen(true)} />} />
        <Route path="/eventos" element={<Events />} />
      </Routes></div>
    </main>
    <NewOrderModal open={newOrderOpen} onClose={() => setNewOrderOpen(false)} onSaved={() => { setNewOrderOpen(false); loadData() }} />
    <ImportOrdersModal open={importOpen} onClose={() => setImportOpen(false)} onSaved={() => { setImportOpen(false); loadData() }} />
    <InvoiceModal open={invoiceOpen} onClose={() => setInvoiceOpen(false)} onSaved={() => { setInvoiceOpen(false); loadData() }} />
    <ProcedureDocumentModal open={procedureOpen} onClose={() => setProcedureOpen(false)} onSaved={() => { setProcedureOpen(false); loadData() }} />
    {copilot && <Copilot onClose={() => setCopilot(false)} />}
  </div></WarehouseContext.Provider>
}

function Header({ onCopilot }) { const location = useLocation(); const title = nav.find(x => x.to === location.pathname)?.label || 'Detalle de operación'; const moreActive = nav.slice(4).some(item => location.pathname.startsWith(item.to)); return <header className={`topbar ${location.pathname === '/' ? 'dashboard-topbar' : ''}`}><div className="container"><div className="row align-items-center gy-3"><div className="col-12 col-xl-3"><NavLink to="/" className="top-brand"><span className="brand-mark"><i className="bi bi-boxes" /></span><span><strong>smart<span>warehouse</span></strong><small>CONTROL CENTER</small></span></NavLink></div><div className="col-12 col-xl-7"><nav className="top-menu nav nav-pills">{nav.slice(0, 4).map(item => <NavLink key={item.to} to={item.to} end={item.end} className={({ isActive }) => isActive ? 'nav-link active' : 'nav-link'}><i className={`bi ${item.icon}`} /><span>{item.label}</span>{item.count && <em>{item.count}</em>}</NavLink>)}<details className={`top-dropdown ${moreActive ? 'active' : ''}`}><summary className="nav-link"><i className="bi bi-three-dots" /><span>Más</span><i className="bi bi-chevron-down dropdown-chevron" /></summary><div className="dropdown-menu show">{nav.slice(4).map(item => <NavLink key={item.to} to={item.to} className={({ isActive }) => isActive ? 'dropdown-item active' : 'dropdown-item'}><i className={`bi ${item.icon}`} /><span>{item.label}</span>{item.count && <em>{item.count}</em>}</NavLink>)}</div></details></nav></div><div className="col-12 col-xl-2"><div className="top-actions justify-content-xl-end"><button className="icon-btn" title="Buscar"><i className="bi bi-search" /></button><button className="icon-btn notification" title="Notificaciones"><i className="bi bi-bell" /><b>3</b></button><button className="copilot-btn" onClick={onCopilot}><i className="bi bi-stars" /> Copilot</button></div></div></div>{location.pathname !== '/' && <div className="row"><div className="col-12"><h1>{title}</h1></div></div>}</div></header> }

const PageTitle = ({ eyebrow, title, children }) => <div className="page-title"><div><div className="eyebrow">{eyebrow}</div><h2>{title}</h2></div><div className="page-actions">{children}</div></div>
const Button = ({ children, primary = false, ...props }) => <button className={primary ? 'btn-main' : 'btn-ghost'} {...props}>{children}</button>
const Risk = ({ risk }) => <span className={`risk risk-${risk}`}><i className="bi bi-circle-fill" /></span>
const Status = ({ children, tone = 'neutral' }) => <span className={`status status-${tone}`}>{children}</span>

function Dashboard({ onNewOrder }) { const { kpis, orders, events } = useWarehouseData(); const primaryOrder = orders.find(order => order.risk === 'red') || orders[0]; return <><PageTitle eyebrow="CENTRO DE CONTROL · 25 SEP 2025" title="Vista general"><Button><i className="bi bi-calendar3" /> Hoy, 25 sep 2025</Button><Button primary onClick={onNewOrder}><i className="bi bi-plus-lg" /> Nuevo pedido</Button></PageTitle>
  <section className="kpi-grid">{kpis.map(k => <div className="kpi-card" key={k.label}><div className={`kpi-icon ${k.tone}`}><i className={`bi ${k.icon}`} /></div><div><span>{k.label}</span><strong>{k.value}</strong><small className={k.tone === 'danger' ? 'text-danger' : 'text-success'}><i className={`bi ${k.tone === 'danger' ? 'bi-exclamation-circle' : 'bi-arrow-up-right'}`} /> {k.change}</small></div></div>)}</section>
  <div className="dashboard-grid"><section className="panel panel-orders"><PanelHead title="Cola de validación" subtitle="Pedidos que requieren decisión" action="Ver todos" />{orders.slice(0, 4).map(order => <OrderRow order={order} key={order.id} />)}</section><section className="panel health-panel"><PanelHead title="Salud operativa" subtitle="Estado del almacén en tiempo real" /><div className="health-score"><div className="score-ring"><strong>94</strong><span>/100</span></div><div><strong>Operación saludable</strong><p>Sin bloqueos críticos en el flujo</p></div></div><div className="health-bars"><Metric label="Pedidos a tiempo" value="96,8%" width="96%" tone="success" /><Metric label="Precisión de stock" value="99,1%" width="99%" tone="info" /><Metric label="Documentación completa" value="82,4%" width="82%" tone="warning" /></div></section></div>
  <div className="dashboard-grid lower"><section className="panel"><PanelHead title="Actividad reciente" subtitle="Eventos del sistema y del motor IA" action="Ver registro" /> <div className="event-list">{events.slice(0, 4).map(e => <EventRow event={e} key={e.time} />)}</div></section><section className="panel insight-panel"><div className="insight-head"><div className="ai-spark"><i className="bi bi-stars" /></div><div><div className="eyebrow">INSIGHT DEL COPILOT</div><h3>Hay una decisión pendiente</h3></div></div><p>{primaryOrder ? <>El pedido <strong>{primaryOrder.id}</strong> presenta una señal que requiere revisión: {primaryOrder.reason}.</> : 'Sin decisiones pendientes en este momento.'}</p><button className="text-link">Revisar recomendación <i className="bi bi-arrow-right" /></button></section></div>
</> }

function PanelHead({ title, subtitle, action }) { return <div className="panel-head"><div><h3>{title}</h3><p>{subtitle}</p></div>{action && <button className="text-link">{action} <i className="bi bi-arrow-up-right" /></button>}</div> }
function OrderRow({ order }) { return <div className="order-row"><Risk risk={order.risk} /><div className="order-main"><strong>{order.id}</strong><span>{order.product}</span></div><div className="order-requester">{order.requester}<small>{order.qty} uds. · {order.total}</small></div><Status tone={order.risk === 'green' ? 'success' : order.risk === 'red' ? 'danger' : 'warning'}>{order.status}</Status><i className="bi bi-chevron-right row-chevron" /></div> }
function Metric({ label, value, width, tone }) { return <div className="metric"><div><span>{label}</span><strong>{value}</strong></div><div className="progress"><div className={`progress-bar bg-${tone}`} style={{ width }} /></div></div> }
function EventRow({ event, onOpen }) { return <div className="event-row"><span className={`event-dot ${event.tone}`} /><div><div><strong>{event.text}</strong><small>{event.time} · {event.type}</small></div><p>{event.detail}</p></div>{onOpen && <button className="text-link" onClick={() => onOpen(event)}>Detalle</button>}</div> }

function Orders({ onNewOrder, onImport }) { const { orders } = useWarehouseData(); return <><PageTitle eyebrow="OPERACIONES / COMPRAS" title="Pedidos y validación"><Button onClick={onImport}><i className="bi bi-file-earmark-spreadsheet" /> Importar plantilla</Button><Button primary onClick={onNewOrder}><i className="bi bi-plus-lg" /> Crear pedido</Button></PageTitle><div className="filter-bar"><div className="search-field"><i className="bi bi-search" /><input placeholder="Buscar por pedido, producto o empleado..." /></div><button>Todos los estados <i className="bi bi-chevron-down" /></button><button>Últimos 30 días <i className="bi bi-chevron-down" /></button><span className="filter-spacer" /><span className="view-toggle active"><i className="bi bi-list" /></span><span className="view-toggle"><i className="bi bi-grid" /></span></div><section className="panel table-panel"><div className="table-meta"><span><strong>{orders.length}</strong> pedidos en cola</span><span className="legend"><Risk risk="green" /> Aprobado <Risk risk="yellow" /> Revisar <Risk risk="red" /> Bloqueado</span></div><table><thead><tr><th>RIESGO</th><th>PEDIDO / PRODUCTO</th><th>SOLICITANTE</th><th>IMPORTE</th><th>ESTADO</th><th>FECHA</th><th /></tr></thead><tbody>{orders.map(o => <tr key={o.id}><td><Risk risk={o.risk} /></td><td><NavLink className="order-link" to={`/pedidos/${o.id}`}><strong>{o.id}</strong><small>{o.product}</small></NavLink></td><td>{o.requester}<small>{o.area}</small></td><td><strong>{o.total}</strong><small>{o.qty} unidades</small></td><td><Status tone={o.risk === 'green' ? 'success' : o.risk === 'red' ? 'danger' : 'warning'}>{o.status}</Status><small className="reason">{o.reason}</small></td><td className="muted">{o.date}</td><td><button className="more"><i className="bi bi-three-dots" /></button></td></tr>)}</tbody></table></section></> }

function OrderDetail() { const { orders, refresh } = useWarehouseData(); const { id } = useParams(); const [validating, setValidating] = useState(false); const [decisionMessage, setDecisionMessage] = useState(''); const order = orders.find(item => item.id === id); if (!order) return <section className="panel"><h3>Cargando pedido...</h3></section>; const validate = async () => { setValidating(true); setDecisionMessage(''); try { const result = await warehouseService.validateOrder(id); setDecisionMessage(`Decisión persistida: ${result.status} · riesgo ${result.risk}.`); await refresh(); } catch (error) { setDecisionMessage(error.message || 'No se pudo persistir la decisión') } finally { setValidating(false) } }; return <><div className="detail-back"><NavLink to="/pedidos"><i className="bi bi-arrow-left" /> Volver a pedidos</NavLink></div><PageTitle eyebrow={`PEDIDO / ${order.id}`} title="Detalle y validación"><Button><i className="bi bi-download" /> Exportar ficha</Button><Button primary onClick={validate} disabled={validating}><i className="bi bi-check2" /> {validating ? 'Validando...' : 'Ejecutar validación'}</Button></PageTitle><div className="detail-grid"><section className="panel"><div className="detail-order-head"><div className={`risk risk-large risk-${order.risk}`}><i className="bi bi-circle-fill" /></div><div><h3>{order.product}</h3><span>{order.id} · creado por {order.requester} · {order.date}</span></div><Status tone={order.risk === 'green' ? 'success' : order.risk === 'red' ? 'danger' : 'warning'}>{order.status}</Status></div><div className="detail-metrics"><div><span>Cantidad solicitada</span><strong>{order.qty} uds.</strong></div><div><span>Importe total</span><strong>{order.total}</strong></div><div><span>Proveedor</span><strong>{order.supplier || '—'}</strong></div><div><span>Stock disponible</span><strong>{order.available_stock || 0} uds.</strong></div></div><div className="decision-note"><i className="bi bi-exclamation-triangle" /><div><strong>Decisión persistida en MySQL</strong><p>{decisionMessage || order.reason}</p></div></div></section><section className="panel validation-panel"><PanelHead title="Validación inteligente" subtitle="Reglas deterministas · API FastAPI" /><ValidationRow icon="bi-box-seam" title="Stock actual" value={`${order.available_stock || 0} uds. disponibles`} status={Number(order.available_stock) >= Number(order.qty) ? 'success' : 'warning'} detail="Comprobación realizada sobre MySQL" /><ValidationRow icon="bi-graph-up" title="Histórico de pedidos" value="Regla determinista" status={order.risk === 'red' ? 'danger' : 'success'} detail={order.reason} /><ValidationRow icon="bi-file-earmark-check" title="Procedimientos" value="Trazabilidad API" status={order.risk === 'red' ? 'danger' : 'success'} detail="La decisión queda persistida en validation_decisions" /></section></div><section className="panel recommendation-panel"><div className="ai-spark"><i className="bi bi-stars" /></div><div><div className="eyebrow">SUGERENCIA EXPLICABLE DEL COPILOT</div><h3>Decisión disponible en la API</h3><p>La validación genera un evento de auditoría y una alerta cuando requiere intervención humana.</p></div><Button primary onClick={validate}>Aplicar sugerencia</Button></section></> }
function ValidationRow({ icon, title, value, status, detail }) { return <div className="validation-row"><div className={`validation-icon ${status}`}><i className={`bi ${icon}`} /></div><div><strong>{title}</strong><span>{detail}</span></div><div className="validation-result"><Status tone={status}>{value}</Status><Risk risk={status === 'success' ? 'green' : status === 'danger' ? 'red' : 'yellow'} /></div></div> }

function Stock() { const { stock } = useWarehouseData(); const lowStock = stock.filter(item => item.status === 'Reponer').length; return <><PageTitle eyebrow="OPERACIONES / INVENTARIO" title="Stock y disponibilidad"><Button><i className="bi bi-upload" /> Importar plantilla</Button><Button primary><i className="bi bi-box-arrow-in-down" /> Registrar entrada</Button></PageTitle><div className="stock-summary"><div><span>Referencias activas</span><strong>{stock.length}</strong><small>datos MySQL</small></div><div><span>Valor de inventario</span><strong>—</strong><small>pendiente de valoración</small></div><div><span>Por debajo de mínimo</span><strong className="danger-number">{lowStock}</strong><small>calculado por API</small></div><div><span>Exactitud inventario</span><strong>—</strong><small>pendiente de movimientos</small></div></div><section className="panel table-panel"><div className="table-meta"><span><strong>Inventario principal</strong> · {stock.length} referencias</span><div className="search-field compact"><i className="bi bi-search" /><input placeholder="Filtrar SKU..." /></div></div><table><thead><tr><th>SKU</th><th>PRODUCTO</th><th>CATEGORÍA</th><th>STOCK</th><th>DEMANDA</th><th>UBICACIÓN</th><th>ESTADO</th></tr></thead><tbody>{stock.map(s => <tr key={s.sku}><td><strong className="sku">{s.sku}</strong></td><td><strong>{s.product}</strong><small>Origen: MySQL</small></td><td>{s.category}</td><td><strong>{s.stock.toLocaleString('es-ES')}</strong><small>Mín. {s.min}</small></td><td><span className={`demand demand-${s.demand.toLowerCase()}`}><i className="bi bi-graph-up" /> {s.demand}</span></td><td className="muted"><i className="bi bi-geo-alt" /> {s.location}</td><td><Status tone={s.status === 'Óptimo' ? 'success' : 'warning'}>{s.status}</Status></td></tr>)}</tbody></table></section></> }

function Receiving() { return <><PageTitle eyebrow="OPERACIONES / LOGÍSTICA" title="Recepción y almacén"><Button><i className="bi bi-printer" /> Imprimir etiquetas</Button><Button primary><i className="bi bi-box-arrow-in-down" /> Nueva recepción</Button></PageTitle><div className="receiving-grid"><section className="panel"><PanelHead title="Muelles de recepción" subtitle="Estado actual · 25 septiembre" /><div className="dock-grid"><Dock name="Muelle 01" supplier="Saltoki Suministros" eta="09:30" status="Descargando" tone="success" /><Dock name="Muelle 02" supplier="General Cable" eta="10:15" status="En camino" tone="info" /><Dock name="Muelle 03" supplier="Roca Sanitario" eta="11:00" status="Programado" tone="warning" /><Dock name="Muelle 04" supplier="Libre" eta="—" status="Disponible" tone="neutral" /></div></section><section className="panel capacity"><PanelHead title="Capacidad del almacén" subtitle="Ocupación por zona" /><div className="warehouse-map"><div className="zone zone-a">A <small>78%</small></div><div className="zone zone-b">B <small>64%</small></div><div className="zone zone-c">C <small>91%</small></div><div className="zone zone-d">D <small>42%</small></div></div><div className="map-legend"><span><i className="legend-dot green" /> Disponible</span><span><i className="legend-dot yellow" /> Atención</span><span><i className="legend-dot red" /> Saturada</span></div></section></div><section className="panel timeline-panel"><PanelHead title="Próximas recepciones" subtitle="Pedidos confirmados con proveedor" action="Ver agenda" />{['PED-2025-00481 · Tubo multicapa PEX 16 mm','PED-2025-00476 · Cable RZ1-K 3G2.5','PED-2025-00470 · Panel LED 60×60 40W'].map((x,i) => <div className="receiving-row" key={x}><div className="time-block"><strong>{['09:30','10:15','11:00'][i]}</strong><small>HOY</small></div><div><strong>{x.split(' · ')[0]}</strong><span>{x.split(' · ')[1]}</span></div><Status tone={i === 0 ? 'success' : 'info'}>{['Descargando','En camino','Programado'][i]}</Status><span className="muted">{['Muelle 01','Muelle 02','Muelle 03'][i]}</span></div>)}</section></> }
function ReceivingFromApi() { const { receipts, orders, refresh } = useWarehouseData(); const [open, setOpen] = useState(false); return <><PageTitle eyebrow="OPERACIONES / LOGÍSTICA" title="Recepción y almacén"><Button><i className="bi bi-printer" /> Imprimir etiquetas</Button><Button primary onClick={() => setOpen(true)}><i className="bi bi-box-arrow-in-down" /> Nueva recepción</Button></PageTitle><div className="receiving-grid"><section className="panel"><PanelHead title="Muelles de recepción" subtitle="Datos recibidos desde FastAPI" /><div className="dock-grid">{receipts.slice(0, 4).map(receipt => <Dock key={receipt.receipt_number} name={receipt.name} supplier={receipt.supplier} eta={receipt.eta} status={receipt.status} tone={receipt.tone} />)}</div></section><section className="panel capacity"><PanelHead title="Capacidad del almacén" subtitle="Ocupación por zona" /><div className="warehouse-map"><div className="zone zone-a">A <small>78%</small></div><div className="zone zone-b">B <small>64%</small></div><div className="zone zone-c">C <small>91%</small></div><div className="zone zone-d">D <small>42%</small></div></div><div className="map-legend"><span><i className="legend-dot green" /> Disponible</span><span><i className="legend-dot yellow" /> Atención</span><span><i className="legend-dot red" /> Saturada</span></div></section></div><section className="panel timeline-panel"><PanelHead title="Recepciones registradas" subtitle="Comparación pedido vs mercancía recibida" />{receipts.slice(0, 8).map(receipt => <div className="receiving-row" key={receipt.receipt_number}><div className="time-block"><strong>{receipt.eta}</strong><small>{receipt.receipt_number}</small></div><div><strong>{receipt.order || receipt.receipt_number}</strong><span>{receipt.product || receipt.supplier} · pedido {receipt.qty} · recibido {receipt.received} · dañado {receipt.damaged}</span></div><Status tone={receipt.tone}>{receipt.resultStatus}</Status><span className="muted">{receipt.name}</span></div>)}</section>{open && <NewReceiptModal orders={orders} onClose={() => setOpen(false)} onSaved={async () => { setOpen(false); await refresh() }} />}</> }

function NewReceiptModal({ orders, onClose, onSaved }) { const [form, setForm] = useState({ order_external_id: '', dock_code: 'Muelle 01', sku: '', received_quantity: '', damaged_quantity: '0', damage_reason: '' }); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const order = orders.find(item => item.id === form.order_external_id); const updateOrder = event => { const selected = orders.find(item => item.id === event.target.value); setForm(current => ({ ...current, order_external_id: event.target.value, sku: selected?.sku || '' })) }; const update = event => setForm(current => ({ ...current, [event.target.name]: event.target.value })); const submit = async event => { event.preventDefault(); setSaving(true); setError(''); try { await warehouseService.createReceipt({ order_external_id: form.order_external_id, dock_code: form.dock_code, lines: [{ sku: form.sku, received_quantity: Number(form.received_quantity), damaged_quantity: Number(form.damaged_quantity), damage_reason: form.damage_reason || null }] }); await onSaved() } catch (err) { setError(err.message || 'No se pudo registrar la recepción') } finally { setSaving(false) } }; return <ModalShell title="Registrar recepción" icon="bi-box-arrow-in-down" onClose={onClose} footer={<><button className="btn-ghost" onClick={onClose}>Cancelar</button><button className="btn-main" form="receipt-form" disabled={saving || !form.order_external_id}>{saving ? 'Registrando…' : 'Registrar entrada'}</button></>}><form id="receipt-form" onSubmit={submit}><div className="row g-3"><div className="col-12"><label className="form-label">Pedido de compra</label><select className="form-select" value={form.order_external_id} onChange={updateOrder} required><option value="">Selecciona un pedido</option>{orders.map(item => <option value={item.id} key={item.id}>{item.id} · {item.product} · solicitado {item.qty}</option>)}</select></div><div className="col-md-6"><label className="form-label">Muelle</label><select className="form-select" name="dock_code" value={form.dock_code} onChange={update}><option>Muelle 01</option><option>Muelle 02</option><option>Muelle 03</option><option>Muelle 04</option></select></div><div className="col-md-6"><label className="form-label">SKU</label><input className="form-control" value={form.sku} readOnly /></div><div className="col-md-6"><label className="form-label">Cantidad recibida</label><input className="form-control" type="number" min="0" step="0.001" name="received_quantity" value={form.received_quantity} onChange={update} required /></div><div className="col-md-6"><label className="form-label">Cantidad dañada</label><input className="form-control" type="number" min="0" step="0.001" name="damaged_quantity" value={form.damaged_quantity} onChange={update} /></div><div className="col-12"><label className="form-label">Motivo / observaciones del daño</label><textarea className="form-control" name="damage_reason" value={form.damage_reason} onChange={update} placeholder="Ej.: embalaje golpeado, pieza rota…" /></div></div>{order && <div className="alert alert-info mt-3 mb-0">Pedido: <strong>{order.qty} unidades</strong>. La API comparará automáticamente solicitado, recibido y dañado.</div>}{error && <div className="alert alert-danger mt-3 mb-0">{error}</div>}</form></ModalShell> }
function Dock({ name, supplier, eta, status, tone }) { return <div className="dock-card"><div className="dock-number"><i className="bi bi-truck" /></div><div><strong>{name}</strong><span>{supplier}</span><small>ETA {eta}</small></div><Status tone={tone}>{status}</Status></div> }

function Suppliers() { const { suppliers } = useWarehouseData(); return <><PageTitle eyebrow="MAESTROS / PARTNERS" title="Proveedores"><Button><i className="bi bi-download" /> Exportar</Button><Button primary><i className="bi bi-plus-lg" /> Añadir proveedor</Button></PageTitle><div className="supplier-cards"><div><i className="bi bi-building" /><strong>{suppliers.length}</strong><span>Proveedores activos</span></div><div><i className="bi bi-link-45deg" /><strong>{suppliers.filter(item => item.status === 'Conectado').length}</strong><span>Conectados por API</span></div><div><i className="bi bi-star" /><strong>{suppliers.length ? (suppliers.reduce((sum, item) => sum + Number(item.rating.replace(',', '.')), 0) / suppliers.length).toFixed(1).replace('.', ',') : '—'} / 5</strong><span>Valoración media</span></div></div><section className="panel table-panel"><div className="table-meta"><span><strong>Red de proveedores</strong></span><div className="search-field compact"><i className="bi bi-search" /><input placeholder="Buscar proveedor..." /></div></div><table><thead><tr><th>PROVEEDOR</th><th>CATEGORÍA</th><th>PEDIDOS YTD</th><th>VALORACIÓN</th><th>PLAZO MEDIO</th><th>ESTADO</th></tr></thead><tbody>{suppliers.map(s => <tr key={s.name}><td><div className="supplier-name"><div className="supplier-avatar">{s.name.slice(0,2).toUpperCase()}</div><strong>{s.name}</strong></div></td><td>{s.category}</td><td>{s.orders}</td><td><span className="rating"><i className="bi bi-star-fill" /> {s.rating}</span></td><td>{s.lead}</td><td><Status tone={s.status === 'Conectado' ? 'success' : 'warning'}>{s.status}</Status></td></tr>)}</tbody></table></section></> }

function Documents({ onUploadInvoice, onUploadProcedure }) { const { invoices, procedures, refresh } = useWarehouseData(); const [busy, setBusy] = useState(''); const [message, setMessage] = useState(''); const missing = procedures.reduce((sum, item) => sum + Number(item.missing || 0), 0); const reconcile = async invoice => { setBusy(invoice.id); setMessage(''); try { const result = await warehouseService.reconcileInvoice(invoice.id); setMessage(`${invoice.id}: ${result.status === 'matched' ? 'conciliación correcta' : 'requiere revisión'} · pedido ${result.order || 'no identificado'}`); await refresh(); } catch (error) { setMessage(error.message || 'No se pudo conciliar la factura') } finally { setBusy('') } }; const exportInvoice = async invoice => { setBusy(invoice.id); setMessage(''); try { await warehouseService.exportInvoice(invoice.id); setMessage(`${invoice.id}: exportada al adaptador contable REST.`); await refresh(); } catch (error) { setMessage(error.message || 'No se pudo exportar la factura') } finally { setBusy('') } }; const download = async format => { setBusy(`download-${format}`); try { await warehouseService.downloadAccountingExport(format); setMessage(`Exportación ${format.toUpperCase()} descargada.`) } catch (error) { setMessage(error.message || 'No se pudo generar la exportación') } finally { setBusy('') } }; return <><PageTitle eyebrow="CONTROL DOCUMENTAL" title="Facturas y documentos"><Button onClick={onUploadInvoice}><i className="bi bi-file-earmark-arrow-up" /> Subir factura PDF</Button><Button onClick={() => download('csv')} disabled={busy.startsWith('download-')}><i className="bi bi-filetype-csv" /> CSV contable</Button><Button primary onClick={() => download('xlsx')} disabled={busy.startsWith('download-')}><i className="bi bi-file-earmark-spreadsheet" /> Excel contable</Button><Button onClick={onUploadProcedure}><i className="bi bi-shield-plus" /> Completar procedimiento</Button></PageTitle><div className="document-banner"><div className="ai-spark"><i className="bi bi-stars" /></div><div><strong>Interpretación, conciliación y exportación activa</strong><p>La operación contrasta factura, pedido, impuestos, total y recepción antes de exportar a contabilidad.</p></div><span className="confidence">{missing} controles pendientes</span></div>{message && <div className="alert alert-info">{message}</div>}<section className="panel table-panel"><div className="table-meta"><span><strong>Facturas recibidas</strong> · {invoices.length} documentos</span><span className="muted">Estados contables persistidos en MySQL</span></div><table><thead><tr><th>DOCUMENTO</th><th>PROVEEDOR</th><th>FECHA</th><th>IMPORTE</th><th>CONCILIACIÓN</th><th>CONTABILIDAD</th><th>ESTADO</th><th /></tr></thead><tbody>{invoices.map(x => <tr key={x.id}><td><div className="doc-name"><i className="bi bi-file-earmark-pdf" /><div><strong>{x.id}</strong><small>{x.type}</small></div></div></td><td>{x.supplier || 'Pendiente identificar'}</td><td>{x.date}</td><td><strong>{x.amount}</strong></td><td><Status tone={x.reconciliationTone}>{x.reconciliationStatus}</Status></td><td><Status tone={x.accountingTone}>{x.accountingStatus}</Status></td><td><Status tone={x.status === 'Exportable' ? 'success' : 'warning'}>{x.status}</Status></td><td>{x.accountingStatus === 'Exportable' && <button className="text-link" onClick={() => exportInvoice(x)} disabled={busy === x.id}>{busy === x.id ? 'Enviando…' : 'Enviar'}</button>}{x.accountingStatus !== 'Exportado' && x.accountingStatus !== 'Exportable' && <button className="text-link" onClick={() => reconcile(x)} disabled={busy === x.id}>{busy === x.id ? 'Conciliando…' : 'Conciliar'}</button>}</td></tr>)}</tbody></table></section><section className="panel procedure-panel"><div className="procedure-icon"><i className="bi bi-shield-check" /></div><div><h3>Documentación obligatoria del proceso</h3><div className="procedure-status-list">{procedures.map(item => <div key={item.code}><span>{item.name}</span><Status tone={item.missing ? 'warning' : 'success'}>{item.missing ? `${item.missing} pendientes` : 'Completo'}</Status></div>)}</div></div><button className="text-link" onClick={onUploadProcedure}>Gestionar procedimientos <i className="bi bi-arrow-right" /></button></section></> }

function Events() { const { events, alerts, alertRules, refresh } = useWarehouseData(); const [severity, setSeverity] = useState('all'); const [type, setType] = useState('all'); const [settingsOpen, setSettingsOpen] = useState(false); const [selected, setSelected] = useState(null); const [message, setMessage] = useState(''); const filteredAlerts = alerts.filter(alert => (severity === 'all' || alert.severity === severity) && (type === 'all' || alert.event_type === type)); const filteredEvents = events.filter(event => (severity === 'all' || event.severity === severity) && (type === 'all' || event.event_type === type)); const critical = filteredAlerts.filter(item => item.tone === 'danger').length; const warnings = filteredAlerts.filter(item => item.tone === 'warning').length; const markRead = async id => { try { await warehouseService.readAlert(id); await refresh(); } catch (error) { setMessage(error.message || 'No se pudo marcar la alerta') } }; const markAll = async () => { try { const result = await warehouseService.readAllAlerts(); setMessage(`${result.marked_read} alertas marcadas como leídas.`); await refresh(); } catch (error) { setMessage(error.message || 'No se pudieron marcar las alertas') } }; const download = async format => { try { await warehouseService.downloadEventsExport(format, { severity, event_type: type }); setMessage(`Registro ${format.toUpperCase()} descargado.`) } catch (error) { setMessage(error.message || 'No se pudo exportar el registro') } }; return <><PageTitle eyebrow="OBSERVABILIDAD / AUDITORÍA" title="Eventos y alertas"><Button onClick={markAll}><i className="bi bi-check2-all" /> Marcar leídas</Button><Button onClick={() => download('csv')}><i className="bi bi-filetype-csv" /> Exportar CSV</Button><Button primary onClick={() => download('xlsx')}><i className="bi bi-file-earmark-spreadsheet" /> Exportar Excel</Button><Button onClick={() => setSettingsOpen(true)}><i className="bi bi-sliders" /> Configurar alertas</Button></PageTitle>{message && <div className="alert alert-info">{message}</div>}<div className="filter-bar"><select value={severity} onChange={event => setSeverity(event.target.value)}><option value="all">Todas las gravedades</option><option value="critical">Crítica</option><option value="warning">Aviso</option><option value="info">Información</option></select><select value={type} onChange={event => setType(event.target.value)}><option value="all">Todos los tipos</option>{[...new Set(events.map(event => event.event_type).filter(Boolean))].map(item => <option value={item} key={item}>{item}</option>)}</select><span className="muted">{filteredEvents.length} eventos · {filteredAlerts.length} alertas visibles</span></div><div className="alert-cards"><div className="alert-critical"><i className="bi bi-exclamation-octagon" /><div><strong>{critical}</strong><span>Alertas críticas pendientes</span></div></div><div className="alert-warning"><i className="bi bi-exclamation-triangle" /><div><strong>{warnings}</strong><span>Requieren atención</span></div></div><div className="alert-ok"><i className="bi bi-check-circle" /><div><strong>{filteredEvents.length}</strong><span>Eventos filtrados</span></div></div></div>{filteredAlerts.length > 0 && <section className="panel event-log alert-log"><div className="table-meta"><span><strong>Alertas pendientes</strong></span><span className="muted">notifications + audit_events</span></div>{filteredAlerts.slice(0, 12).map((alert, index) => <div className="event-row" key={alert.id || index}><span className={`event-dot ${alert.tone}`} /><div><div><strong>{alert.title}</strong><small>{alert.time} · {alert.event_type}</small></div><p>{alert.body}</p></div><button className="text-link" onClick={() => markRead(alert.id)}>Marcar leída</button></div>)}</section>}{settingsOpen && <AlertRulesModal rules={alertRules} onClose={() => setSettingsOpen(false)} onSaved={async () => { setSettingsOpen(false); await refresh() }} /> }{selected && <EventDetailModal event={selected} onClose={() => setSelected(null)} />}<section className="panel event-log"><div className="table-meta"><span><strong>Registro de actividad</strong></span><span className="muted">Payload completo disponible por evento</span></div>{filteredEvents.slice(0, 50).map((event, index) => <EventRow event={event} onOpen={setSelected} key={event.id || index} />)}</section></> }

function EventDetailModal({ event, onClose }) { return <ModalShell title="Detalle del evento" icon="bi-braces" onClose={onClose} footer={<button className="btn-ghost" onClick={onClose}>Cerrar</button>}><div className="detail-metrics"><div><span>ID</span><strong>{event.id}</strong></div><div><span>Tipo</span><strong>{event.event_type}</strong></div><div><span>Gravedad</span><strong>{event.severity}</strong></div><div><span>Agregado</span><strong>{event.aggregate_type} · {event.aggregate_id}</strong></div></div><pre className="mt-4 p-3 bg-light rounded" style={{ fontSize: '12px', maxHeight: '360px', overflow: 'auto' }}>{JSON.stringify(event.payload, null, 2)}</pre></ModalShell> }

function AlertRulesModal({ rules, onClose, onSaved }) { const [form, setForm] = useState({ code: '', name: '', description: '', event_type: 'ai.validation', severity: 'warning', recipients: '', channels: 'in_app' }); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const update = event => setForm(current => ({ ...current, [event.target.name]: event.target.value })); const submit = async event => { event.preventDefault(); setSaving(true); setError(''); try { await warehouseService.createAlertRule({ ...form, recipients: form.recipients.split(',').map(item => item.trim()).filter(Boolean), channels: form.channels.split(',').map(item => item.trim()).filter(Boolean) }); await onSaved(); } catch (err) { setError(err.message || 'No se pudo crear la regla') } finally { setSaving(false) } }; const toggle = async rule => { try { await warehouseService.updateAlertRule(rule.id, { code: rule.code, name: rule.name, description: rule.description, event_type: rule.event_type, severity: rule.severity, enabled: !rule.enabled, recipients: rule.recipients, channels: rule.channels }); await onSaved() } catch (err) { setError(err.message || 'No se pudo actualizar la regla') } }; return <ModalShell title="Configuración de alertas" icon="bi-sliders" onClose={onClose} footer={<button className="btn-ghost" onClick={onClose}>Cerrar</button>}><div className="mb-4"><h6>Reglas activas</h6>{rules.map(rule => <div className="d-flex align-items-center justify-content-between border-bottom py-2" key={rule.id}><div><strong>{rule.name}</strong><small className="d-block text-muted">{rule.event_type} · {rule.severity} · {rule.recipients.join(', ') || 'sin destinatarios'}</small></div><button className="text-link" onClick={() => toggle(rule)}>{rule.enabled ? 'Desactivar' : 'Activar'}</button></div>)}</div><form onSubmit={submit}><h6>Nueva regla</h6><div className="row g-2"><div className="col-md-4"><input className="form-control" name="code" placeholder="Código" value={form.code} onChange={update} required /></div><div className="col-md-8"><input className="form-control" name="name" placeholder="Nombre de la regla" value={form.name} onChange={update} required /></div><div className="col-md-6"><input className="form-control" name="event_type" placeholder="Tipo de evento" value={form.event_type} onChange={update} required /></div><div className="col-md-3"><select className="form-select" name="severity" value={form.severity} onChange={update}><option value="info">Información</option><option value="warning">Aviso</option><option value="critical">Crítica</option></select></div><div className="col-md-3"><input className="form-control" name="channels" placeholder="Canales" value={form.channels} onChange={update} /></div><div className="col-12"><input className="form-control" name="recipients" placeholder="Destinatarios separados por coma" value={form.recipients} onChange={update} required /></div><div className="col-12"><textarea className="form-control" name="description" placeholder="Descripción" value={form.description} onChange={update} /></div></div>{error && <div className="alert alert-danger mt-3 mb-0">{error}</div>}<button className="btn-main mt-3" disabled={saving}>{saving ? 'Guardando…' : 'Crear regla'}</button></form></ModalShell> }

function ModalShell({ title, icon, onClose, children, footer }) { return <div className="modal-backdrop-custom"><div className="modal d-block" tabIndex="-1" role="dialog"><div className="modal-dialog modal-dialog-centered modal-lg"><div className="modal-content"><div className="modal-header"><h5 className="modal-title"><i className={`bi ${icon}`} /> {title}</h5><button type="button" className="btn-close" aria-label="Cerrar" onClick={onClose} /></div><div className="modal-body">{children}</div>{footer && <div className="modal-footer">{footer}</div>}</div></div></div></div> }

function NewOrderModal({ open, onClose, onSaved }) { const { stock, suppliers } = useWarehouseData(); const [form, setForm] = useState({ sku: '', quantity: 1, unit_price: '', supplier_code: '', external_order_id: '' }); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); if (!open) return null; const update = event => setForm(current => ({ ...current, [event.target.name]: event.target.value })); const submit = async event => { event.preventDefault(); setSaving(true); setError(''); try { await warehouseService.createOrder({ ...form, quantity: Number(form.quantity), unit_price: Number(form.unit_price) }); setForm({ sku: '', quantity: 1, unit_price: '', supplier_code: '', external_order_id: '' }); onSaved(); } catch (err) { setError(err.message || 'No se pudo crear el pedido') } finally { setSaving(false) } }; return <ModalShell title="Nuevo pedido" icon="bi-cart-plus" onClose={onClose} footer={<><button className="btn-ghost" onClick={onClose}>Cancelar</button><button className="btn-main" form="new-order-form" disabled={saving}>{saving ? 'Guardando...' : 'Crear pedido'}</button></>}><form id="new-order-form" onSubmit={submit}><div className="row g-3"><div className="col-md-8"><label className="form-label">Producto / SKU</label><select className="form-select" name="sku" value={form.sku} onChange={update} required><option value="">Selecciona una referencia</option>{stock.map(item => <option value={item.sku} key={item.sku}>{item.sku} · {item.product}</option>)}</select></div><div className="col-md-4"><label className="form-label">Cantidad</label><input className="form-control" type="number" min="1" name="quantity" value={form.quantity} onChange={update} required /></div><div className="col-md-6"><label className="form-label">Proveedor</label><select className="form-select" name="supplier_code" value={form.supplier_code} onChange={update} required><option value="">Selecciona proveedor</option>{suppliers.map(item => <option value={item.code} key={item.code}>{item.name}</option>)}</select></div><div className="col-md-3"><label className="form-label">Precio unitario (€)</label><input className="form-control" type="number" min="0.01" step="0.01" name="unit_price" value={form.unit_price} onChange={update} required /></div><div className="col-md-3"><label className="form-label">Referencia externa</label><input className="form-control" name="external_order_id" value={form.external_order_id} onChange={update} placeholder="Opcional" /></div></div>{error && <div className="alert alert-danger mt-3 mb-0">{error}</div>}<div className="alert alert-info mt-4 mb-0"><i className="bi bi-info-circle me-2" />El pedido se crea como pendiente y pasará por la validación determinista.</div></form></ModalShell> }

function ImportOrdersModal({ open, onClose, onSaved }) { const [file, setFile] = useState(null); const [result, setResult] = useState(null); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); if (!open) return null; const submit = async event => { event.preventDefault(); if (!file) return; setSaving(true); setError(''); try { const response = await warehouseService.importOrders(file); setResult(response); if (response.error_count === 0) setTimeout(onSaved, 600); } catch (err) { setError(err.message || 'No se pudo importar la plantilla') } finally { setSaving(false) } }; return <ModalShell title="Importar pedidos" icon="bi-file-earmark-spreadsheet" onClose={onClose} footer={<><button className="btn-ghost" onClick={onClose}>Cerrar</button><button className="btn-main" form="import-orders-form" disabled={!file || saving}>{saving ? 'Importando...' : 'Importar pedidos'}</button></>}><form id="import-orders-form" onSubmit={submit}><div className="import-dropzone"><i className="bi bi-cloud-arrow-up" /><strong>Selecciona la plantilla de pedidos</strong><span>Formatos admitidos: .csv y .xlsx</span><input className="form-control mt-3" type="file" accept=".csv,.xlsx" onChange={event => { setFile(event.target.files?.[0] || null); setResult(null) }} /></div><div className="template-columns mt-3"><strong>Columnas esperadas</strong><code>external_order_id · sku · product_description · quantity · unit_price · supplier_code</code></div>{result && <div className={`alert ${result.error_count ? 'alert-warning' : 'alert-success'} mt-3 mb-0`}>Importados: <strong>{result.imported_count}</strong> · Errores: <strong>{result.error_count}</strong>{result.errors?.length > 0 && <small className="d-block mt-2">{result.errors.slice(0, 3).map(item => `Fila ${item.row}: ${item.message}`).join(' · ')}</small>}</div>}{error && <div className="alert alert-danger mt-3 mb-0">{error}</div>}</form></ModalShell> }

function InvoiceModal({ open, onClose, onSaved }) { const [file, setFile] = useState(null); const [result, setResult] = useState(null); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); if (!open) return null; const submit = async event => { event.preventDefault(); if (!file) return; setSaving(true); setError(''); try { const response = await warehouseService.uploadInvoice(file); setResult(response); if (response.status === 'exportable') setTimeout(onSaved, 700); } catch (err) { setError(err.message || 'No se pudo procesar la factura') } finally { setSaving(false) } }; const reviewText = result?.ocr_applied ? 'Se ha aplicado OCR. Los campos reconocidos quedan con confianza reducida y requieren revisión humana.' : 'Faltan datos fiables o no se ha identificado el proveedor.'; return <ModalShell title="Subir factura PDF" icon="bi-file-earmark-pdf" onClose={onClose} footer={<><button className="btn-ghost" onClick={onClose}>Cerrar</button><button className="btn-main" form="invoice-form" disabled={!file || saving}>{saving ? 'Interpretando...' : 'Procesar factura'}</button></>}><form id="invoice-form" onSubmit={submit}><div className="import-dropzone"><i className="bi bi-file-earmark-pdf" /><strong>Selecciona una factura PDF</strong><span>Se extraerán proveedor, número, fecha, impuestos y total</span><input className="form-control mt-3" type="file" accept="application/pdf,.pdf" onChange={event => { setFile(event.target.files?.[0] || null); setResult(null) }} /></div>{result && <div className={`alert ${result.status === 'exportable' ? 'alert-success' : 'alert-warning'} mt-3 mb-0`}>Factura <strong>{result.invoice_number}</strong>: {result.status === 'exportable' ? 'lista para exportar a contabilidad.' : reviewText}{result.low_confidence_fields?.length > 0 && <small className="d-block mt-2">Campos a revisar: {result.low_confidence_fields.join(', ')}</small>}</div>}{error && <div className="alert alert-danger mt-3 mb-0">{error}</div>}<div className="alert alert-info mt-4 mb-0"><i className="bi bi-shield-check me-2" />El documento queda guardado en almacenamiento local, auditado en eventos y preparado para revisión humana.</div></form></ModalShell> }

function ProcedureDocumentModal({ open, onClose, onSaved }) { const { orders, procedures } = useWarehouseData(); const [form, setForm] = useState({ externalId: '', procedureCode: '' }); const [file, setFile] = useState(null); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); if (!open) return null; const update = event => setForm(current => ({ ...current, [event.target.name]: event.target.value })); const submit = async event => { event.preventDefault(); if (!file || !form.externalId || !form.procedureCode) return; setSaving(true); setError(''); try { await warehouseService.uploadProcedureDocument(form.externalId, form.procedureCode, file); setForm({ externalId: '', procedureCode: '' }); setFile(null); onSaved(); } catch (err) { setError(err.message || 'No se pudo completar el procedimiento') } finally { setSaving(false) } }; return <ModalShell title="Completar procedimiento" icon="bi-shield-plus" onClose={onClose} footer={<><button className="btn-ghost" onClick={onClose}>Cerrar</button><button className="btn-main" form="procedure-document-form" disabled={!file || !form.externalId || !form.procedureCode || saving}>{saving ? 'Guardando...' : 'Marcar como completo'}</button></>}><form id="procedure-document-form" onSubmit={submit}><div className="row g-3"><div className="col-12"><label className="form-label">Pedido</label><select className="form-select" name="externalId" value={form.externalId} onChange={update} required><option value="">Selecciona un pedido</option>{orders.map(order => <option value={order.id} key={order.id}>{order.id} · {order.product}</option>)}</select></div><div className="col-12"><label className="form-label">Procedimiento obligatorio</label><select className="form-select" name="procedureCode" value={form.procedureCode} onChange={update} required><option value="">Selecciona un procedimiento</option>{procedures.map(item => <option value={item.code} key={item.code}>{item.name}</option>)}</select></div><div className="col-12"><label className="form-label">Documento justificativo</label><input className="form-control" type="file" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx" onChange={event => setFile(event.target.files?.[0] || null)} required /><div className="form-text">Se guardará, vinculará al pedido y se registrará en auditoría.</div></div></div>{error && <div className="alert alert-danger mt-3 mb-0">{error}</div>}<div className="alert alert-info mt-4 mb-0"><i className="bi bi-info-circle me-2" />Al completar el procedimiento, el control pasará a estado <strong>complete</strong>.</div></form></ModalShell> }

function Copilot({ onClose }) { const { orders, stock, events } = useWarehouseData(); const [query, setQuery] = useState(''); const [sent, setSent] = useState(false); const pending = orders.filter(order => order.risk !== 'green'); const critical = pending.find(order => order.risk === 'red') || pending[0]; const lowStock = stock.filter(item => item.status === 'Reponer'); const answer = query.toLowerCase().includes('stock') ? `Hay ${lowStock.length} referencias por debajo del mínimo en MySQL.` : query.toLowerCase().includes('alert') ? `La API ha registrado ${events.filter(event => event.tone === 'danger' || event.tone === 'warning').length} eventos que requieren atención.` : `He encontrado ${pending.length} pedidos que requieren revisión humana. El más urgente es ${critical?.id || '—'}: ${critical?.product || 'sin producto'}, ${critical?.reason || 'pendiente de análisis'}.`; return <div className="copilot-overlay" onClick={onClose}><aside className="copilot-panel" onClick={e => e.stopPropagation()}><div className="copilot-header"><div className="copilot-title"><div className="ai-spark"><i className="bi bi-stars" /></div><div><strong>Warehouse Copilot</strong><span>Contexto operativo · actualizado desde API</span></div></div><button className="icon-btn" onClick={onClose}><i className="bi bi-x-lg" /></button></div><div className="copilot-body"><div className="copilot-welcome"><div className="ai-spark large"><i className="bi bi-stars" /></div><h3>¿En qué puedo ayudarte?</h3><p>Consulto pedidos, stock, proveedores, documentos y eventos de tu operación.</p></div><div className="suggestions"><button onClick={() => setQuery('¿Qué pedidos necesitan revisión humana?')}>Pedidos para revisar <i className="bi bi-arrow-up-right" /></button><button onClick={() => setQuery('¿Qué referencias están por debajo del mínimo?')}>Stock crítico <i className="bi bi-arrow-up-right" /></button><button onClick={() => setQuery('Resume las alertas de hoy')}>Alertas de hoy <i className="bi bi-arrow-up-right" /></button></div>{sent && <div className="chat-answer"><small>WAREHOUSE COPILOT · API</small><p>{answer}</p><button className="text-link">Abrir resultados <i className="bi bi-arrow-right" /></button></div>}</div><form className="copilot-input" onSubmit={e => { e.preventDefault(); setSent(true); }}><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Pregunta sobre tu operación..." /><button><i className="bi bi-arrow-up" /></button></form></aside></div> }

export default App
